    def vowel_change(ch):
        return ch if ch not in "aeiouAEIOU" else chr(ord(ch) + 2)

    # Combine both functions into one for simplicity
    def transform_char(ch):
        return switch_case(ch) if ch.isalpha() else ch

    m = "".join(transform_char(c) for c in message)
    return "".join(vowel_change(c) for c in m)

