def find_biggest_even_in_range(x, y):
    """
    This function finds the biggest even number within the given range [x, y].

    Parameters:
    x (int): The start of the range.
    y (int): The end of the range.

    Returns:
    int: The biggest even number in the range or -1 if no such number exists.
    """
    # Ensure x is less than or equal to y
    if x > y:
        return -1

    # Check if both x and y are even
    if x % 2 == 0 and y % 2 == 0:
        return max(x, y)
    elif x % 2 != 0 and y % 2 != 0:
        return -1
    else:
        # Find the largest even number in the range
        if x % 2 == 0:
            return x
        else:
            return y - 1

