def match_parens(lst):
    """
    Check if concatenating two strings from the given list can result in a balanced string of parentheses.

    Args:
    lst (list): A list containing two strings consisting only of '(' and ')'.

    Returns:
    str: 'Yes' if a balanced string can be formed, 'No' otherwise.
    """

    def is_balanced(s: str) -> bool:
        balance = 0
        for char in s:
            if char == '(':
                balance += 1
            elif char == ')':
                balance -= 1
            if balance < 0:
                return False
        return balance == 0

    # Try concatenating in both orders
    return "Yes" if is_balanced(lst[0] + lst[1]) or is_balanced(lst[1] + lst[0]) else "No"

